1	import { type ReceiptExtract } from '$lib/utils/sanitize';
2	import { Mistral } from '@mistralai/mistralai';
3	import { chatComplete } from '@mistralai/mistralai/funcs/chatComplete.js';
4	import { type ChatCompletionResponse } from '@mistralai/mistralai/models/components';
5	
6	const ocrModel = 'pixtral-12b-2409';
7	// #{#rdc2a} Requests `raw_date_text` — the date exactly as printed, verbatim — alongside
8	// the interpreted `transaction_date`, so code can re-parse ambiguous formats (#{#rdc4a}).
9	export const receiptPrompt: string = `Extract fields from the receipt. Respond as JSON with keys: transaction_date (YYYY-MM-DD), raw_date_text (the date exactly as printed on the receipt, verbatim — keep the original separators and digits, do not reinterpret), total_amount (number), tax (number), merchant_name (string), currency (ISO 4217), credit_card_name (string), credit_card_last_4 (string). Default currency to CAD unless the receipt explicitly states a different currency. A bare "$" sign means CAD.`;
10	
11	export type FileCategory = 'pdf' | 'image';
12	
13	export class OcrService {
14		private client: Mistral | null = null;
15	
16		/**
17		 * Initialize the Mistral client with API key from environment
18		 */
19		private async initClient(): Promise<Mistral> {
20			if (this.client) {
21				return this.client;
22			}
23	
24			// Use private environment variable (server-side only)
25			const { MISTRAL_API_KEY } = await import('$env/static/private');
26			if (!MISTRAL_API_KEY) {
27				throw new Error(
28					'MISTRAL_API_KEY environment variable is not set. Please configure it in your .env file.'
29				);
30			}
31	
32			this.client = new Mistral({ apiKey: MISTRAL_API_KEY });
33			return this.client;
34		}
35	
36		/**
37		 * Supported MIME types for OCR processing
38		 */
39		private static readonly SUPPORTED_TYPES = {
40			PDF: ['application/pdf'],
41			IMAGE: ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/heic', 'image/heif']
42		} as const;
43	
44		/**
45		 * Categorizes a MIME type into pdf or image
46		 */
47		private categorizeMimeType(mimeType: string): FileCategory | null {
48			// Normalize: remove parameters and convert to lowercase
49			const normalized = mimeType.split(';')[0].trim().toLowerCase();
50	
51			if (OcrService.SUPPORTED_TYPES.PDF.includes(normalized as any)) {
52				return 'pdf';
53			}
54	
55			if (OcrService.SUPPORTED_TYPES.IMAGE.includes(normalized as any)) {
56				return 'image';
57			}
58	
59			return null;
60		}
61	
62		/**
63		 * Extracts receipt data from a URL (image or PDF)
64		 * Mistral's pixtral model handles both images and PDFs directly
65		 *
66		 * @param fileUrl - URL of the file to process
67		 * @param mimeType - MIME type of the file
68		 * @returns Extracted receipt data
69		 * @throws Error if validation fails or API call fails
70		 */
71		async extractFromUrl(fileUrl: string, mimeType: string): Promise<ReceiptExtract> {
72			try {
73				// Validate inputs
74				if (!fileUrl || typeof fileUrl !== 'string' || fileUrl.trim().length === 0) {
75					throw new Error('Invalid file URL provided');
76				}
77	
78				if (!mimeType || typeof mimeType !== 'string') {
79					throw new Error('MIME type is required');
80				}
81	
82				// Categorize and validate MIME type
83				const category = this.categorizeMimeType(mimeType);
84	
85				if (!category) {
86					const supported = [
87						...OcrService.SUPPORTED_TYPES.PDF,
88						...OcrService.SUPPORTED_TYPES.IMAGE
89					].join(', ');
90					throw new Error(`Unsupported file type: ${mimeType}. Supported types: ${supported}`);
91				}
92	
93				// Initialize client
94				const client = await this.initClient();
95	
96				console.log(`OcrService.extractFromUrl() processing ${category}: ${fileUrl}`);
97	
98				// Build request based on file category
99				const contentType = category === 'pdf' ? 'document_url' : 'image_url';
100				const urlKey = category === 'pdf' ? 'documentUrl' : 'imageUrl';
101	
102				const maxRetries = 3;
103				let chatResponse;
104				for (let attempt = 1; attempt <= maxRetries; attempt++) {
105					chatResponse = await chatComplete(client, {
106						model: ocrModel,
107						responseFormat: { type: 'json_object' },
108						messages: [
109							{
110								role: 'user',
111								content: [
112									{ type: 'text', text: receiptPrompt },
113									{
114										type: contentType,
115										[urlKey]: fileUrl
116									} as any
117								]
118							}
119						]
120					});
121	
122					if (chatResponse.ok) break;
123	
124					// Retry on transient errors (rate limiting, image fetch failures)
125					const errorStr = String(chatResponse.error);
126					const isRetryable = errorStr.includes('400') || errorStr.includes('429');
127					if (!isRetryable || attempt === maxRetries) {
128						throw new Error(`Mistral OCR request failed: ${chatResponse.error}`);
129					}
130					console.warn(`Mistral OCR attempt ${attempt} failed, retrying in ${attempt * 2}s...`);
131					await new Promise((r) => setTimeout(r, attempt * 2000));
132				}
133	
134				const completionResponse: ChatCompletionResponse = chatResponse.value;
135	
136				// Validate response structure
137				if (!completionResponse.choices || completionResponse.choices.length === 0) {
138					throw new Error('Mistral API returned no choices in response');
139				}
140	
141				const firstChoice = completionResponse.choices[0];
142				if (!firstChoice.message || !firstChoice.message.content) {
143					throw new Error('Mistral API returned empty message content');
144				}
145	
146				// Log all choices for debugging (using forEach instead of map)
147				completionResponse.choices.forEach((choice, index) => {
148					console.log(`Choice ${index}:`, choice.message.content);
149				});
150	
151				const jsonString = firstChoice.message.content as string;
152				const receipt = this.parseTransactionJson(jsonString);
153				return receipt;
154			} catch (error) {
155				// Re-throw with more context
156				const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
157				throw new Error(`OCR extraction failed: ${errorMessage}`);
158			}
159		}
160	
161		/**
162		 * Parses JSON response from Mistral API, handling markdown code blocks
163		 *
164		 * @param jsonString - Raw JSON string from API (may be wrapped in markdown)
165		 * @returns Parsed receipt extract object
166		 * @throws Error if parsing fails
167		 */
168		parseTransactionJson(jsonString: string): ReceiptExtract {
169			try {
170				if (!jsonString || typeof jsonString !== 'string') {
171					throw new Error('Invalid JSON string provided');
172				}
173	
174				let cleanedJson = jsonString.trim();
175	
176				// Remove markdown code block markers if present
177				// Handles variations: ```json, ```JSON, ``` with json, etc.
178				const codeBlockRegex = /^```(?:json|JSON)?\s*\n?([\s\S]*?)\n?```$/;
179				const match = cleanedJson.match(codeBlockRegex);
180	
181				if (match) {
182					cleanedJson = match[1].trim();
183				}
184	
185				// Parse the JSON
186				const parsedData = JSON.parse(cleanedJson);
187	
188				// Basic validation - ensure it's an object
189				if (!parsedData || typeof parsedData !== 'object' || Array.isArray(parsedData)) {
190					throw new Error('Parsed data is not a valid object');
191				}
192	
193				// Return with type assertion
194				// Note: Further validation should be done by the sanitizeExtract function
195				return parsedData as ReceiptExtract;
196			} catch (error) {
197				const errorMessage = error instanceof Error ? error.message : 'Unknown parsing error';
198				throw new Error(`Failed to parse transaction data: ${errorMessage}`);
199			}
200		}
201	}
