82	describe('#{#exp6a} Uncategorized Expenses Queue View', () => {
83		describe('Filter Logic', () => {
84			/**
85			 * #{#exp6a} Criterion 2: Filter must display only expenses with category_id = NULL
86			 */
87			function filterUncategorizedExpenses(expenses: Expense[]): Expense[] {
88				return expenses.filter((expense) => expense.category_id === null);
89			}
90	
91			it('should filter to show only uncategorized expenses', () => {
92				const filtered = filterUncategorizedExpenses(mockExpenses);
93	
94				expect(filtered.length).toBe(2);
95				expect(filtered.every((e) => e.category_id === null)).toBe(true);
96				expect(filtered[0].merchant_name).toBe('Amazon');
97				expect(filtered[1].merchant_name).toBe('Best Buy');
98			});
99	
100			it('should return empty array when all expenses are categorized', () => {
101				const categorizedExpenses = mockExpenses.filter((e) => e.category_id !== null);
102				const filtered = filterUncategorizedExpenses(categorizedExpenses);
103	
104				expect(filtered.length).toBe(0);
105			});
106	
107			it('should return all expenses when none are categorized', () => {
108				const uncategorizedExpenses = mockExpenses.map((e) => ({
109					...e,
110					category_id: null,
111					category_name: null,
112					category_color: null
113				}));
114				const filtered = filterUncategorizedExpenses(uncategorizedExpenses);
115	
116				expect(filtered.length).toBe(mockExpenses.length);
117			});
118		});
119	
120		describe('Count Calculation', () => {
121			/**
122			 * #{#exp6a} Criterion 3: Filter must show count "X uncategorized expenses"
123			 */
124			function getUncategorizedCount(expenses: Expense[]): number {
125				return expenses.filter((e) => e.category_id === null).length;
126			}
127	
128			it('should count uncategorized expenses correctly', () => {
129				const count = getUncategorizedCount(mockExpenses);
130				expect(count).toBe(2);
131			});
132	
133			it('should return 0 when all expenses are categorized', () => {
134				const categorizedExpenses = mockExpenses.filter((e) => e.category_id !== null);
135				const count = getUncategorizedCount(categorizedExpenses);
136				expect(count).toBe(0);
137			});
138	
139			it('should return total count when all expenses are uncategorized', () => {
140				const uncategorizedExpenses = mockExpenses.map((e) => ({
141					...e,
142					category_id: null
143				}));
144				const count = getUncategorizedCount(uncategorizedExpenses);
145				expect(count).toBe(mockExpenses.length);
