149		describe('Sorting by Date', () => {
150			/**
151			 * #{#exp6a} Criterion 4: Uncategorized expenses sorted by date (newest first)
152			 */
153			function sortByDateDesc(expenses: Expense[]): Expense[] {
154				return [...expenses].sort(
155					(a, b) => new Date(b.transaction_date).getTime() - new Date(a.transaction_date).getTime()
156				);
157			}
158	
159			it('should sort uncategorized expenses by date (newest first)', () => {
160				const uncategorized = mockExpenses.filter((e) => e.category_id === null);
161				const sorted = sortByDateDesc(uncategorized);
162	
163				expect(sorted.length).toBe(2);
164				expect(sorted[0].transaction_date).toBe('2025-12-03'); // Amazon (newer)
165				expect(sorted[1].transaction_date).toBe('2025-12-02'); // Best Buy (older)
166			});
167	
168			it('should handle single uncategorized expense', () => {
169				const singleExpense = [mockExpenses[2]]; // Amazon
170				const sorted = sortByDateDesc(singleExpense);
171	
172				expect(sorted.length).toBe(1);
173				expect(sorted[0].merchant_name).toBe('Amazon');
174			});
175	
176			it('should handle empty array', () => {
177				const sorted = sortByDateDesc([]);
178				expect(sorted.length).toBe(0);
179			});
180	
181			it('should sort all expenses by date descending', () => {
182				const sorted = sortByDateDesc(mockExpenses);
183	
184				// Verify descending order
185				for (let i = 0; i < sorted.length - 1; i++) {
186					const current = new Date(sorted[i].transaction_date).getTime();
187					const next = new Date(sorted[i + 1].transaction_date).getTime();
188					expect(current).toBeGreaterThanOrEqual(next);
189				}
190			});
191		});
