193		describe('URL Parameter Handling', () => {
194			/**
195			 * #{#exp6a} Criterion 7: Filter state persists in URL (?filter=uncategorized)
196			 */
197			function parseFilterFromURL(url: string): string | null {
198				const params = new URLSearchParams(url.split('?')[1] || '');
199				return params.get('filter');
200			}
201	
202			function createFilterURL(filter: string | null): string {
203				if (!filter) return '/expenses';
204				return `/expenses?filter=${encodeURIComponent(filter)}`;
205			}
206	
207			it('should parse "uncategorized" filter from URL', () => {
208				const url = '/expenses?filter=uncategorized';
209				const filter = parseFilterFromURL(url);
210				expect(filter).toBe('uncategorized');
211			});
212	
213			it('should return null when no filter in URL', () => {
214				const url = '/expenses';
215				const filter = parseFilterFromURL(url);
216				expect(filter).toBeNull();
217			});
218	
219			it('should create URL with uncategorized filter', () => {
220				const url = createFilterURL('uncategorized');
221				expect(url).toBe('/expenses?filter=uncategorized');
222			});
223	
224			it('should create URL without filter when filter is null', () => {
225				const url = createFilterURL(null);
226				expect(url).toBe('/expenses');
227			});
228	
229			it('should handle URL with other query parameters', () => {
230				const url = '/expenses?startDate=2025-01-01&filter=uncategorized&endDate=2025-12-31';
231				const filter = parseFilterFromURL(url);
232				expect(filter).toBe('uncategorized');
233			});
234		});
235	});
