237	describe('#{#exp7a} Category Filter and Analytics', () => {
238		describe('Category Filter Logic', () => {
239			/**
240			 * #{#exp7a} Criterion 2: Show only expenses in selected category
241			 */
242			function filterByCategory(expenses: Expense[], categoryId: string | null): Expense[] {
243				if (!categoryId) return expenses;
244				return expenses.filter((e) => e.category_id === categoryId);
245			}
246	
247			/**
248			 * #{#exp7a} Criterion 4: Multiple categories selectable (OR logic)
249			 */
250			function filterByCategories(expenses: Expense[], categoryIds: string[]): Expense[] {
251				if (categoryIds.length === 0) return expenses;
252				return expenses.filter((e) => e.category_id && categoryIds.includes(e.category_id));
253			}
254	
255			it('should filter expenses by single category', () => {
256				const filtered = filterByCategory(mockExpenses, 'cat-groceries');
257	
258				expect(filtered.length).toBe(2);
259				expect(filtered.every((e) => e.category_id === 'cat-groceries')).toBe(true);
260			});
261	
262			it('should return all expenses when category is null', () => {
263				const filtered = filterByCategory(mockExpenses, null);
264				expect(filtered.length).toBe(mockExpenses.length);
265			});
266	
267			it('should return empty array when no expenses match category', () => {
268				const filtered = filterByCategory(mockExpenses, 'cat-nonexistent');
269				expect(filtered.length).toBe(0);
270			});
271	
272			it('should filter by multiple categories with OR logic', () => {
273				const filtered = filterByCategories(mockExpenses, ['cat-groceries', 'cat-transport']);
274	
275				expect(filtered.length).toBe(3);
276				expect(filtered.some((e) => e.category_id === 'cat-groceries')).toBe(true);
277				expect(filtered.some((e) => e.category_id === 'cat-transport')).toBe(true);
278			});
279	
280			it('should return all expenses when category list is empty', () => {
281				const filtered = filterByCategories(mockExpenses, []);
282				expect(filtered.length).toBe(mockExpenses.length);
283			});
284	
285			it('should exclude uncategorized expenses from category filter', () => {
286				const filtered = filterByCategories(mockExpenses, ['cat-groceries']);
287	
288				expect(filtered.every((e) => e.category_id !== null)).toBe(true);
289			});
290		});
291	
292		describe('Expense Count per Category', () => {
293			/**
294			 * #{#exp7a} Criterion 3: Show count like "Groceries (24)"
295			 */
296			function getExpenseCountByCategory(expenses: Expense[]): Record<string, number> {
297				const counts: Record<string, number> = {};
298	
299				expenses.forEach((expense) => {
300					const key = expense.category_id || 'uncategorized';
301					counts[key] = (counts[key] || 0) + 1;
302				});
303	
304				return counts;
305			}
306	
307			it('should count expenses per category', () => {
308				const counts = getExpenseCountByCategory(mockExpenses);
309	
310				expect(counts['cat-groceries']).toBe(2);
311				expect(counts['cat-transport']).toBe(1);
312				expect(counts['uncategorized']).toBe(2);
313			});
314	
315			it('should handle all expenses in one category', () => {
316				const sameCategory = mockExpenses.map((e) => ({
317					...e,
318					category_id: 'cat-groceries'
319				}));
320				const counts = getExpenseCountByCategory(sameCategory);
321	
322				expect(counts['cat-groceries']).toBe(mockExpenses.length);
323			});
324	
325			it('should handle all uncategorized expenses', () => {
326				const uncategorized = mockExpenses.map((e) => ({
327					...e,
328					category_id: null
329				}));
330				const counts = getExpenseCountByCategory(uncategorized);
331	
332				expect(counts['uncategorized']).toBe(mockExpenses.length);
333			});
334		});
335	
336		describe('Spending Summary Calculations', () => {
337			/**
338			 * #{#exp7a} Criterion 6: Summary panel shows total spending per category
339			 */
340			interface CategorySpending {
341				categoryId: string;
342				categoryName: string;
343				totalAmount: number;
344				expenseCount: number;
345			}
346	
347			function calculateSpendingSummary(expenses: Expense[]): CategorySpending[] {
348				const summaryMap = new Map<string, CategorySpending>();
349	
350				expenses.forEach((expense) => {
351					const catId = expense.category_id || 'uncategorized';
352					const catName = expense.category_name || 'Uncategorized';
353	
354					if (!summaryMap.has(catId)) {
355						summaryMap.set(catId, {
356							categoryId: catId,
357							categoryName: catName,
358							totalAmount: 0,
359							expenseCount: 0
360						});
361					}
362	
363					const summary = summaryMap.get(catId)!;
364					summary.totalAmount += expense.total_amount;
365					summary.expenseCount += 1;
366				});
367	
368				return Array.from(summaryMap.values());
369			}
370	
371			function calculateGrandTotal(expenses: Expense[]): number {
372				return expenses.reduce((sum, expense) => sum + expense.total_amount, 0);
373			}
374	
375			it('should calculate spending summary by category', () => {
376				const summary = calculateSpendingSummary(mockExpenses);
377	
378				const groceries = summary.find((s) => s.categoryId === 'cat-groceries');
379				expect(groceries).toBeDefined();
380				expect(groceries!.totalAmount).toBeCloseTo(123.45 + 156.78, 2);
381				expect(groceries!.expenseCount).toBe(2);
382			});
383	
384			it('should include uncategorized in summary', () => {
385				const summary = calculateSpendingSummary(mockExpenses);
386	
387				const uncategorized = summary.find((s) => s.categoryId === 'uncategorized');
388				expect(uncategorized).toBeDefined();
389				expect(uncategorized!.totalAmount).toBeCloseTo(89.12 + 299.99, 2);
390				expect(uncategorized!.expenseCount).toBe(2);
391			});
392	
393			it('should calculate grand total correctly', () => {
394				const total = calculateGrandTotal(mockExpenses);
395	
396				const expected = 123.45 + 45.67 + 89.12 + 299.99 + 156.78;
397				expect(total).toBeCloseTo(expected, 2);
398			});
399	
400			it('should handle empty expense list', () => {
401				const summary = calculateSpendingSummary([]);
402				expect(summary.length).toBe(0);
403	
404				const total = calculateGrandTotal([]);
405				expect(total).toBe(0);
406			});
407	
408			it('should sort summary by total amount descending', () => {
409				const summary = calculateSpendingSummary(mockExpenses);
410				const sorted = [...summary].sort((a, b) => b.totalAmount - a.totalAmount);
411	
