// Build request based on file category
const fileChunk: ContentChunk =
	category === 'pdf'
		? { type: 'document_url', documentUrl: fileUrl }
		: { type: 'image_url', imageUrl: fileUrl };

const maxRetries = 3;
let chatResponse;
for (let attempt = 1; attempt <= maxRetries; attempt++) {
	chatResponse = await chatComplete(client, {
		model: ocrModel,
		responseFormat: { type: 'json_object' },
		messages: [
			{
				role: 'user',
				content: [{ type: 'text', text: receiptPrompt }, fileChunk]
			}
		]
	});

	if (chatResponse?.ok) break;

	// Retry on transient errors (rate limiting, image fetch failures)
	const errorStr = chatResponse ? String(chatResponse.error) : 'no response from Mistral SDK';
	const isRetryable = errorStr.includes('400') || errorStr.includes('429');
	if (!isRetryable || attempt === maxRetries) {
		throw new Error(`Mistral OCR request failed: ${errorStr}`);
	}
	console.warn(`Mistral OCR attempt ${attempt} failed, retrying in ${attempt * 2}s...`);
	await new Promise((r) => setTimeout(r, attempt * 2000));
}

// Unreachable in practice (the loop breaks with an ok response or throws), but
// guards the compiler-visible undefined case the same soft way as every other
// OCR failure: callers in ocrProcessor catch this and return { success: false }.
if (!chatResponse?.ok) {
	throw new Error('Mistral OCR request failed: no response from Mistral SDK');
}

