/**
 * Test Suite for OcrService — verbatim printed-date request.
 *
 * #{#rdc2a authority=platform} - Capture verbatim printed date
 *
 * The receipt OCR prompt must ask Mistral for one extra field: the date exactly as
 * printed (`raw_date_text`), alongside the interpreted `transaction_date`. This is a
 * verbatim-copy request, not an interpretation hint (ruled-out approach).
 *
 * Also covers the fail-soft guards around the Mistral SDK response. The SDK is
 * fully mocked — these tests must never call the real Mistral API.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { chatComplete } from '@mistralai/mistralai/funcs/chatComplete.js';
import { OcrService, receiptPrompt } from './OcrService';

vi.mock('$env/static/private', () => ({ MISTRAL_API_KEY: 'test-api-key' }));
vi.mock('@mistralai/mistralai/funcs/chatComplete.js', () => ({ chatComplete: vi.fn() }));

type ChatCompleteResult = Awaited<ReturnType<typeof chatComplete>>;

const mockChatComplete = vi.mocked(chatComplete);

function okResult(content: string): ChatCompleteResult {
	return {
		ok: true,
		value: {
			id: 'chat-1',
			object: 'chat.completion',
			model: 'pixtral-12b-2409',
			usage: { promptTokens: 1, completionTokens: 1, totalTokens: 2 },
			created: 1767225600,
			choices: [
				{
					index: 0,
					message: { role: 'assistant', content },
					finishReason: 'stop'
				}
			]
		}
	};
}

describe('#{#rdc2a} - Capture verbatim printed date', () => {
	it('requests the raw_date_text field', () => {
		expect(receiptPrompt).toContain('raw_date_text');
	});

	it('still requests the interpreted transaction_date field', () => {
		expect(receiptPrompt).toContain('transaction_date');
	});

	it('describes raw_date_text as verbatim / as printed', () => {
		expect(receiptPrompt.toLowerCase()).toMatch(/verbatim|as printed|exactly as/);
	});
});

