	it('returns the parsed extract on a successful response', async () => {
		mockChatComplete.mockResolvedValueOnce(
			okResult('{"merchant_name":"Test Store","total_amount":12.34,"currency":"CAD"}')
		);

		const service = new OcrService();
		const extract = await service.extractFromUrl('https://example.test/receipt.jpg', 'image/jpeg');

		expect(extract.merchant_name).toBe('Test Store');
		expect(extract.total_amount).toBe(12.34);
		expect(mockChatComplete).toHaveBeenCalledTimes(1);
	});

	it('fails soft with a wrapped error when the SDK yields no response at all', async () => {
		// Simulates the compiler-visible "response is undefined" case: the service must
		// surface a normal Error (which ocrProcessor converts to { success: false }),
		// never crash with a TypeError deep in the pipeline.
		mockChatComplete.mockResolvedValueOnce(undefined as unknown as ChatCompleteResult);

		const service = new OcrService();

		await expect(
			service.extractFromUrl('https://example.test/receipt.jpg', 'image/jpeg')
		).rejects.toThrow(/OCR extraction failed: Mistral OCR request failed: no response/);
	});

	it('fails soft with a wrapped error on a non-retryable SDK failure', async () => {
		mockChatComplete.mockResolvedValueOnce({
			ok: false,
			error: new Error('503 Service Unavailable')
		} as ChatCompleteResult);

		const service = new OcrService();

		await expect(
			service.extractFromUrl('https://example.test/receipt.pdf', 'application/pdf')
		).rejects.toThrow(/OCR extraction failed: Mistral OCR request failed/);
		// Non-retryable errors must not be retried
		expect(mockChatComplete).toHaveBeenCalledTimes(1);
	});
});

